describe('Table Row Selection Highlighting', () => {
  beforeEach(() => {
    cy.visit('/table');
  });

  it('should highlight selected rows with a different background color', () => {
    // Verify table is visible
    cy.get('[data-testid="data-table"]').should('be.visible');

    // Verify rows exist
    cy.get('[data-testid="table-row"]').should('have.length.greaterThan', 0);

    // Select the first row
    cy.get('[data-testid="table-row"]').first().click();

    // Verify the first row is highlighted
    cy.get('[data-testid="table-row"]').first().should('have.class', 'selected-row');
    cy.get('[data-testid="table-row"]').first().should('have.css', 'background-color', 'rgb(230, 243, 255)');

    // Verify the highlight color is different from default
    cy.get('[data-testid="table-row"]').first().should('not.have.class', 'default-row');

    // Select the second row
    cy.get('[data-testid="table-row"]').eq(1).click();

    // Verify the second row is highlighted
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'selected-row');
    cy.get('[data-testid="table-row"]').eq(1).should('have.css', 'background-color', 'rgb(230, 243, 255)');

    // Verify the first row is still highlighted
    cy.get('[data-testid="table-row"]').first().should('have.class', 'selected-row');

    // Verify both rows are highlighted
    cy.get('[data-testid="table-row"]').should('have.class', 'selected-row');
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'selected-row');
  });

  it('should unhighlight a row when it is deselected', () => {
    // Select the first row
    cy.get('[data-testid="table-row"]').first().click();
    cy.get('[data-testid="table-row"]').first().should('have.class', 'selected-row');

    // Select the second row
    cy.get('[data-testid="table-row"]').eq(1).click();
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'selected-row');

    // Deselect the first row by clicking it again
    cy.get('[data-testid="table-row"]').first().click();

    // Verify the first row is no longer highlighted
    cy.get('[data-testid="table-row"]').first().should('not.have.class', 'selected-row');
    cy.get('[data-testid="table-row"]').first().should('have.css', 'background-color', 'rgb(255, 255, 255)');

    // Verify the second row remains highlighted
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'selected-row');

    // Select the first row again
    cy.get('[data-testid="table-row"]').first().click();
    cy.get('[data-testid="table-row"]').first().should('have.class', 'selected-row');

    // Verify the second row is still highlighted
    cy.get('[data-testid="table-row"]').eq(1).should('have.class', 'selected-row');
  });
});
